<main class="write-main nl-main"><div class="writer-head"><div><span class="writer-kicker">Delivery evidence</span><h1><?=e($campaign['title'])?></h1><p><?=e(newsletter_status_label($campaign['status']))?> · <?=intval($campaign['audience_size'])?> recipients in the scheduled snapshot.</p></div><a class="wbtn" href="<?=url('/write/newsletter/'.$campaign['id'])?>">Edition controls</a></div>
<div class="nl-stats"><?php foreach($counts as$status=>$count):?><section class="nl-card"><span class="nl-number"><?=intval($count)?></span><h2><?=e(newsletter_status_label($status))?></h2></section><?php endforeach;?></div>
<p class="nl-help">“Accepted” records the provider’s acknowledgement. “Delivery confirmed”, bounce and complaint states require verified provider feedback. An unknown outcome is held for investigation and is never automatically retried. “Processing complete” means every recipient has a recorded outcome; it does not mean every message reached an inbox.</p>
<section class="nl-section"><h2>Recipient records</h2><div class="nl-table-wrap"><table class="nl-table"><thead><tr><th>Subscriber</th><th>Status</th><th>Provider accepted</th><th>Feedback</th><th>Detail</th></tr></thead><tbody>
<?php if(!$deliveries):?><tr><td colspan="5">This edition has no recipient snapshot yet.</td></tr><?php endif;?>
<?php foreach($deliveries as$delivery):$recipientLabel=!empty($delivery['email'])&&hash_equals($delivery['email_hash'],newsletter_email_hash($delivery['email']))?$delivery['email']:'Address changed since scheduling';?><tr><td><?php if($delivery['subscriber_id']):?><a href="<?=url('/write/newsletter/subscribers/'.$delivery['subscriber_id'])?>"><?=e($recipientLabel)?></a><?php else:?>Removed subscriber<?php endif;?></td><td><?=e(newsletter_status_label($delivery['status']))?></td><td><?=e(newsletter_local_time($delivery['accepted_at']))?></td><td><?=e(newsletter_local_time($delivery['feedback_at']))?></td><td><?=e(str_replace('_',' ',$delivery['last_error']??''))?></td></tr><?php endforeach;?></tbody></table></div>
<nav class="nl-pagination" aria-label="Recipient pages"><?php if($pageNumber>1):?><a href="<?=url('/write/newsletter/'.$campaign['id'].'/report?page='.($pageNumber-1))?>">← Previous</a><?php endif;?><span>Page <?=intval($pageNumber)?></span><?php if($pageNumber*50<(int)$campaign['audience_size']):?><a href="<?=url('/write/newsletter/'.$campaign['id'].'/report?page='.($pageNumber+1))?>">Next →</a><?php endif;?></nav></section>
<details class="nl-card nl-section"><summary>Edition history</summary><ol class="nl-history"><?php foreach($events as$event):?><li><strong><?=e(ucfirst(str_replace('_',' ',$event['event_type'])))?></strong><p><?=e($event['note'])?></p><small><?=e(newsletter_local_time($event['created_at']))?></small></li><?php endforeach;?></ol></details>
